'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { FolderPlusIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

import { fadePresence } from './motion-parts';
import { DraftProjectRow, ProjectRow, type Project } from './project-rows';

const WORKSPACE_NAME = 'Mossline';

function projectCountOf(count: number) {
  if (count === 0) {
    return 'No projects';
  }
  if (count === 1) {
    return '1 project';
  }
  return `${count} projects`;
}

function EmptyProjects({ onCreate }: { onCreate: () => void }) {
  return (
    <div className='hairline-border border-foreground/20 flex flex-col items-center rounded-xl border-dashed px-6 py-12 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        <FolderPlusIcon />
      </span>
      <p className='text-muted-foreground mt-4 max-w-sm text-[13px] text-balance'>
        {WORKSPACE_NAME} has no projects yet, create one to group the tasks
        behind a goal
      </p>
      <Button onClick={onCreate} className='mt-4'>
        <PlusIcon />
        Create project
      </Button>
    </div>
  );
}

export default function EmptyStates01() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [isCreating, setIsCreating] = useState(false);
  const [nextId, setNextId] = useState(1);
  const hasProjects = projects.length > 0;
  const showsList = hasProjects || isCreating;

  function startCreating() {
    setIsCreating(true);
  }

  function cancelCreating() {
    setIsCreating(false);
  }

  function create(name: string) {
    const project: Project = { id: `project-${nextId}`, name };
    setProjects((current) => [project, ...current]);
    setNextId((current) => current + 1);
    setIsCreating(false);
  }

  function remove(projectId: string) {
    setProjects((current) =>
      current.filter((project) => project.id !== projectId)
    );
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-8 sm:px-8 sm:py-10'>
      <div className='mx-auto max-w-2xl'>
        <div className='flex h-8 items-center justify-between gap-3'>
          <div className='min-w-0'>
            <h1 className='text-sm font-semibold'>Projects</h1>
            <p className='text-muted-foreground text-xs'>
              {projectCountOf(projects.length)}
            </p>
          </div>
          {hasProjects && (
            <Button onClick={startCreating} disabled={isCreating}>
              <PlusIcon />
              New project
            </Button>
          )}
        </div>
        <AnimatedSize className='mt-5'>
          <div className='relative'>
            <AnimatePresence mode='popLayout' initial={false}>
              {!showsList && (
                <motion.div key='empty' {...fadePresence()}>
                  <EmptyProjects onCreate={startCreating} />
                </motion.div>
              )}
              {showsList && (
                <motion.ul
                  key='list'
                  aria-label='Projects'
                  {...fadePresence()}
                  className='bg-card hairline-ring ring-border hairline-divide-y divide-border overflow-clip rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
                >
                  <AnimatePresence initial={false}>
                    {isCreating && (
                      <DraftProjectRow
                        key='draft'
                        onCreate={create}
                        onCancel={cancelCreating}
                      />
                    )}
                    {projects.map((project) => (
                      <ProjectRow
                        key={project.id}
                        project={project}
                        onDelete={remove}
                      />
                    ))}
                  </AnimatePresence>
                </motion.ul>
              )}
            </AnimatePresence>
          </div>
        </AnimatedSize>
      </div>
    </div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { FolderIcon, TrashIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import { heightPresenceOf } from './motion-parts';

export type Project = {
  id: string;
  name: string;
};

function ProjectTile() {
  return (
    <span className='keycap-3d text-muted-foreground flex size-7 shrink-0 items-center justify-center rounded-md'>
      <FolderIcon className='size-3.5' />
    </span>
  );
}

export function ProjectRow({
  project,
  onDelete,
}: {
  project: Project;
  onDelete: (projectId: string) => void;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='flex h-14 items-center gap-3 ps-3 pe-2'>
        <ProjectTile />
        <div className='min-w-0 flex-1'>
          <p className='truncate text-[13px] font-medium'>{project.name}</p>
          <p className='text-muted-foreground text-xs'>No tasks yet</p>
        </div>
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label={`Delete ${project.name}`}
          onClick={() => onDelete(project.id)}
          className='text-muted-foreground'
        >
          <TrashIcon />
        </Button>
      </div>
    </motion.li>
  );
}

export function DraftProjectRow({
  onCreate,
  onCancel,
}: {
  onCreate: (name: string) => void;
  onCancel: () => void;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const [name, setName] = useState('');
  const trimmed = name.trim();
  const canCreate = trimmed.length > 0;

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canCreate) {
      return;
    }
    onCreate(trimmed);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      onCancel();
    }
  }

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <form
        onSubmit={submit}
        className='flex min-h-14 flex-wrap items-center gap-x-3 gap-y-2 px-3 py-2.5'
      >
        <ProjectTile />
        <Input
          ref={inputRef}
          value={name}
          onChange={(event) => setName(event.target.value)}
          onKeyDown={handleKeyDown}
          aria-label='Project name'
          placeholder='Project name'
          className='min-w-0 flex-1 basis-40'
        />
        <div className='ms-auto flex items-center gap-1'>
          <Button type='button' variant='ghost' size='sm' onClick={onCancel}>
            Cancel
          </Button>
          <Button type='submit' size='sm' disabled={!canCreate}>
            Create
          </Button>
        </div>
      </form>
    </motion.li>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={variants}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
